package bench.web;
import bench.db.Db; import bench.util.Util; import jakarta.servlet.http.*; import java.io.*; import java.sql.*;
public class InviteServlet extends HttpServlet { protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws IOException{ try(Connection c=Db.get()){ c.setAutoCommit(false); int org=Util.org(req); PreparedStatement lock=c.prepareStatement("SELECT seats_limit FROM orgs WHERE id=? FOR UPDATE"); lock.setInt(1,org); lock.executeQuery(); PreparedStatement count=c.prepareStatement("SELECT COUNT(*) FROM invites WHERE org_id=?"); count.setInt(1,org); ResultSet rs=count.executeQuery(); rs.next(); if(rs.getInt(1)>=1){c.rollback();resp.sendError(409,"full");return;} PreparedStatement ps=c.prepareStatement("INSERT INTO invites(email,org_id) VALUES(?,?)"); ps.setString(1,req.getParameter("email")); ps.setInt(2,org); ps.executeUpdate(); c.commit(); Util.text(resp,"invited"); }catch(Exception e){resp.setStatus(500);Util.text(resp,"internal error");} } }
